# ==============================================================================
# 🏆 ARC-AGI-3 — Q-TRINITY v7.0   (Go-Explore / R-max, harness-correct)
#
# Fixes derived from agents/agent.py + arc_agi recon:
#   F1  engine resolved from `arcengine` (the module the harness itself uses)
#   F2  action_data ALWAYS set (incl. game_id) -> no None.model_dump() crash
#   F3  do_action_request wrapped in a lock -> no ACTION6 coord races (110 threads)
#   F4  append_frame truncated + recorder disabled -> no RAM / disk blow-up
#   F5  wall-clock deadline in is_done -> swarm closes the scorecard cleanly
#   F6  choose_action/take_action never raise -> a thread can never die silently
#   F7  volatility-masked state key -> HUD/timers no longer defeat all memory
#   F8  Go-Explore replay + reset-semantics detection (full vs level reset)
#   F9  block-size-aware ACTION6 menu (64x64 frames are coarse logical grids)
#   F10 per-game JSON telemetry incl. click_api / click_race / fps
# ==============================================================================
import os, sys, glob, json, shutil, time, importlib, subprocess, traceback
from pathlib import Path
from types import SimpleNamespace as NS
import numpy as np
import pandas as pd

WORK_DIR = Path("/kaggle/working"); WORK_DIR.mkdir(parents=True, exist_ok=True)
AGENT_REPO_DST = WORK_DIR / "ARC-AGI-3-Agents"
STATS_DIR = WORK_DIR / "q_stats"; STATS_DIR.mkdir(exist_ok=True)

BUDGET_HOURS = float(os.getenv("QT_BUDGET_HOURS", "8.0"))   # <-- tune to the rerun limit
RESERVE_MIN  = 15.0                                          # leave time to close scorecard

print("=" * 74)
print("🚀 ARC-AGI-3 — Q-TRINITY v7.0 (Go-Explore / R-max, harness-correct)")
print("=" * 74)

# ---------------------------------------------------------------- STEP 0
pd.DataFrame([{"row_id": "0_0", "game_id": "placeholder",
               "end_of_game": True, "score": 0.0}]) \
  .to_parquet(str(WORK_DIR / "submission.parquet"), index=False)
print("[✓] submission.parquet placeholder written.")

# ---------------------------------------------------------------- STEP 1
wheel_dirs = glob.glob("/kaggle/input/**/arc_agi_3_wheels", recursive=True)
if wheel_dirs:
    print(f"[1/6] Installing offline wheels from {wheel_dirs[0]}")
    subprocess.run([sys.executable, "-m", "pip", "install", "--no-index",
                    f"--find-links={wheel_dirs[0]}", "arc-agi", "arcengine",
                    "python-dotenv", "pydantic", "requests", "--quiet"], check=False)
else:
    print("[1/6] No offline wheels found — using preinstalled packages.")

repo_srcs = glob.glob("/kaggle/input/**/ARC-AGI-3-Agents", recursive=True)
if repo_srcs:
    print(f"[2/6] Copying agent repo from {repo_srcs[0]}")
    shutil.copytree(repo_srcs[0], AGENT_REPO_DST, dirs_exist_ok=True)
elif not AGENT_REPO_DST.exists():
    (AGENT_REPO_DST / "agents" / "templates").mkdir(parents=True, exist_ok=True)

# ---- make `arcengine` importable in THIS kernel (needed for preflight) ------
def ensure_arcengine():
    importlib.invalidate_caches()
    try:
        import arcengine; return arcengine.__file__
    except Exception:
        pass
    roots = set()
    for pat in (str(AGENT_REPO_DST) + "/**/arcengine/__init__.py",
                "/kaggle/input/**/arcengine/__init__.py"):
        for c in glob.glob(pat, recursive=True):
            roots.add(str(Path(c).parent.parent))
    for r in sorted(roots):
        if r not in sys.path:
            sys.path.insert(0, r)
        importlib.invalidate_caches()
        try:
            import arcengine; return arcengine.__file__
        except Exception:
            continue
    if wheel_dirs:
        subprocess.run([sys.executable, "-m", "pip", "install", "--no-index",
                        f"--find-links={wheel_dirs[0]}", "arcengine", "--quiet"],
                       check=False)
        importlib.invalidate_caches()
        try:
            import arcengine; return arcengine.__file__
        except Exception:
            pass
    return None

if str(AGENT_REPO_DST) not in sys.path:
    sys.path.insert(0, str(AGENT_REPO_DST))
_ae = ensure_arcengine()
print(f"      arcengine -> {_ae}")

# ---- register the agent WITHOUT clobbering the shipped __init__ ------------
for init_file in glob.glob(f"{AGENT_REPO_DST}/**/agents/__init__.py", recursive=True):
    try:
        p = Path(init_file); src = p.read_text(encoding="utf-8")
        if "q_trinity" not in src:
            p.write_text(src + (
                "\n\n# --- q_trinity registration (appended) ---\n"
                "try:\n"
                "    from .templates.my_agent import MyAgent as _QT\n"
                "    AVAILABLE_AGENTS['my_agent'] = _QT\n"
                "    AVAILABLE_AGENTS['MyAgent'] = _QT\n"
                "except Exception:\n"
                "    import traceback; traceback.print_exc()\n"
            ), encoding="utf-8")
            print(f"      registered in {p}")
    except Exception:
        traceback.print_exc()

# ---------------------------------------------------------------- STEP 2
HP = {
    # state abstraction
    "vol_window": 50, "vol_thresh": 0.70, "vol_max_frac": 0.15,
    # ACTION6 menu
    "max_clicks_per_state": 64, "menu_hard_cap": 320, "menu_cache_cap": 30000,
    # search
    "bfs_max_nodes": 4000, "edge_repeat_cap": 2,
    # episode control
    "stagnation_limit": 400, "max_replay": 800,
    # movement tie-breakers
    "wall_penalty": 5.0, "landmark_weight": 0.5, "unvisited_bonus": 1.0,
    # engineering
    "stats_every": 150, "max_actions": 2000000, "frames_keep": 4,
    "max_consec_errors": 25, "wide_lock": 0,
}
(WORK_DIR / "q_trinity_params.json").write_text(json.dumps(HP, indent=2), encoding="utf-8")

# ---------------------------------------------------------------- STEP 3
AGENT_SOURCE = r'''"""Q-TRINITY v7.0 — Go-Explore / R-max solver for ARC-AGI-3."""
import os, json, time, random, hashlib, threading, importlib, pkgutil
from enum import Enum
from math import gcd
from collections import deque, defaultdict
from typing import Any, Dict, List, Optional, Set, Tuple

import numpy as np

try:
    from scipy import ndimage as _ndi
except Exception:
    _ndi = None

# ===================================================== F1: ENGINE RESOLUTION
# agents/agent.py itself does `from arcengine import ...`, so arcengine is the
# authoritative module. Using the same objects guarantees enum identity.
ENGINE_SRC: List[str] = []
GameAction = GameState = FrameData = None
try:
    import arcengine as _ae
    GameAction, GameState = _ae.GameAction, _ae.GameState
    FrameData = getattr(_ae, "FrameData", None)
    ENGINE_SRC.append("arcengine")
except Exception:
    for _mn in ("arc_agi.api", "arc_agi.wrapper", "arc_agi.models", "arc_agi"):
        try:
            _m = importlib.import_module(_mn)
        except Exception:
            continue
        if GameAction is None and hasattr(_m, "GameAction"):
            GameAction = _m.GameAction; ENGINE_SRC.append("GameAction<-" + _mn)
        if GameState is None and hasattr(_m, "GameState"):
            GameState = _m.GameState; ENGINE_SRC.append("GameState<-" + _mn)
        if FrameData is None and hasattr(_m, "FrameData"):
            FrameData = _m.FrameData; ENGINE_SRC.append("FrameData<-" + _mn)

ENGINE_OK = (GameAction is not None and GameState is not None)

if not ENGINE_OK:                                   # local-dev shim ONLY
    ENGINE_SRC.append("SHIM")
    class GameState(Enum):                                   # type: ignore
        NOT_PLAYED = 0; NOT_FINISHED = 1; WIN = 2; GAME_OVER = 3
    class GameAction(Enum):                                  # type: ignore
        RESET = 0; ACTION1 = 1; ACTION2 = 2; ACTION3 = 3
        ACTION4 = 4; ACTION5 = 5; ACTION6 = 6
        def is_simple(self): return 1 <= self.value <= 5
        def is_complex(self): return self.value == 6
        def set_data(self, d): self.action_data = d; return d
    class FrameData:                                         # type: ignore
        def __init__(self, **k):
            self.game_id = k.get("game_id", "")
            self.frame = k.get("frame", [])
            self.state = k.get("state", GameState.NOT_FINISHED)
            self.levels_completed = k.get("levels_completed", 0)
            self.available_actions = k.get("available_actions", [1, 2, 3, 4, 5, 6])
            self.guid = k.get("guid", "")
            self.full_reset = k.get("full_reset", False)

try:
    from agents.agent import Agent
    BASE_REAL = True
except Exception:
    BASE_REAL = False
    class Agent(object):                                     # type: ignore
        MAX_ACTIONS = 80
        def __init__(self, *a, **k):
            for key, val in k.items():
                setattr(self, key, val)
            self.frames = []
            self.action_counter = 0

_ACT_LOCK = threading.RLock()     # F3: GameAction members are process-global
DEADLINE = float(os.getenv("QT_DEADLINE_EPOCH", "0") or 0) or float("inf")


# ===================================================== helpers
def _sname(x) -> str:
    return str(getattr(x, "name", x)).upper()


def _aid(a) -> int:
    v = getattr(a, "value", a)
    if isinstance(v, (tuple, list)):
        v = v[0]
    try:
        return int(v)
    except Exception:
        n = _sname(a)
        if n.startswith("ACTION"):
            try: return int(n[6:])
            except Exception: return -1
        return 0 if n == "RESET" else -1


def label_components(mask: np.ndarray):
    if _ndi is not None:
        return _ndi.label(mask)
    H, W = mask.shape
    lab = np.zeros((H, W), dtype=np.int32); n = 0
    for y, x in np.argwhere(mask):
        if lab[y, x]: continue
        n += 1; lab[y, x] = n; st = [(int(y), int(x))]
        while st:
            cy, cx = st.pop()
            for ny, nx in ((cy-1, cx), (cy+1, cx), (cy, cx-1), (cy, cx+1)):
                if 0 <= ny < H and 0 <= nx < W and mask[ny, nx] and not lab[ny, nx]:
                    lab[ny, nx] = n; st.append((ny, nx))
    return lab, n


class MyAgent(Agent):
    DEFAULT_HP = __HP_PLACEHOLDER__
    MAX_ACTIONS = int(os.getenv("QT_MAX_ACTIONS", str(DEFAULT_HP["max_actions"])))

    # =================================================== construction
    def __init__(self, *args: Any, **kwargs: Any) -> None:
        if not args:
            for k, v in {"card_id": "local", "game_id": "local_game",
                         "agent_name": "q_trinity_v7", "ROOT_URL": "",
                         "record": False, "arc_env": None, "tags": []}.items():
                kwargs.setdefault(k, v)
        kwargs["record"] = False                 # F4: never start the Recorder
        try:
            super().__init__(*args, **kwargs)
        except Exception:
            try:
                kwargs.pop("tags", None)
                super().__init__(*args, **kwargs)
            except Exception:
                for k, v in kwargs.items(): setattr(self, k, v)
                self.frames = []; self.action_counter = 0

        self.hp = dict(self.DEFAULT_HP)
        p = "/kaggle/working/q_trinity_params.json"
        if os.path.exists(p):
            try: self.hp.update(json.load(open(p)))
            except Exception: pass

        gid = str(getattr(self, "game_id", "game"))
        self.rng = random.Random(1337 + (abs(hash(gid)) % 100000))

        # ---- persistent world model (survives every RESET) ----
        self.T: Dict[Tuple[bytes, tuple], bytes] = {}
        self.adj: Dict[bytes, Dict[tuple, bytes]] = defaultdict(dict)
        self.rev: Dict[bytes, Set[Tuple[bytes, tuple]]] = defaultdict(set)
        self.reward_at: Dict[bytes, Dict[tuple, float]] = defaultdict(dict)
        self.trap_edges: Set[Tuple[bytes, tuple]] = set()
        self.dead: Set[bytes] = set()
        self.tried: Dict[bytes, Set[tuple]] = defaultdict(set)
        self.menu: Dict[bytes, List[tuple]] = {}
        self.menu_ext: Dict[bytes, int] = {}
        self.key_sig: Dict[Tuple[bytes, tuple], tuple] = {}
        self.visits: Dict[bytes, int] = defaultdict(int)
        self.gv = 0
        self._memo: Dict[tuple, tuple] = {}

        self.click_stats: Dict[tuple, List[int]] = defaultdict(lambda: [0, 0])
        self.aid_stats: Dict[int, List[int]] = defaultdict(lambda: [0, 0])

        self.avatar_color: Optional[int] = None
        self.avatar_votes: Dict[int, int] = defaultdict(int)
        self.action_deltas: Dict[int, Tuple[float, float]] = {}
        self.wall_votes: Dict[int, int] = defaultdict(int)
        self.wall_colors: Set[int] = set()
        self.pushable_colors: Set[int] = set()

        self.best_score = 0.0
        self.best_traj: List[tuple] = []
        self.best_states: List[bytes] = []
        self.reset_preserves: Optional[bool] = None
        self._pre_reset_score = 0.0
        self._await_reset = False

        self._vol = None; self._mask = None; self._mask_frozen = False
        self._blk = 1; self._blk_shape = None

        self._pending_data: Optional[Dict[str, int]] = None
        self._schema_c: Optional[int] = None
        self._schema_s: Optional[int] = None
        self.click_api = "unset"
        self.click_race = 0
        self._errors = 0
        self._last_err = ""

        self.avail_ids: Set[int] = set(); self.act_by_id: Dict[int, Any] = {}
        self.av_pos = None; self.av_pts = None; self.landmarks: List = []

        self.t = 0; self.episodes = 0; self.deaths = 0; self.resets = 0
        self.replay_steps = 0; self.mode_counts: Dict[str, int] = defaultdict(int)
        self._t0 = time.time()
        safe = "".join(c if c.isalnum() or c in "-_" else "_" for c in gid)
        self._stats_path = "/kaggle/working/q_stats/%s.json" % safe

        self._begin_episode()

    # =================================================== F4: memory / disk
    def start_recording(self) -> None:
        return                                  # recorder disabled on purpose

    def append_frame(self, frame) -> None:
        try:
            self.frames.append(frame)
            keep = int(self.hp.get("frames_keep", 4))
            if len(self.frames) > keep:
                del self.frames[:-keep]
            if getattr(frame, "guid", None):
                self.guid = frame.guid
        except Exception:
            pass

    # =================================================== F2/F3: action I/O
    def _set_action_data(self, action) -> str:
        pend = self._pending_data
        gid = str(getattr(self, "game_id", ""))
        if pend:
            cands = [{"game_id": gid, "x": pend["x"], "y": pend["y"]},
                     {"x": pend["x"], "y": pend["y"]},
                     {"game_id": gid, "x": pend["x"], "y": pend["y"], "reasoning": {}}]
            cached = self._schema_c
        else:
            cands = [{"game_id": gid}, {}, {"game_id": gid, "reasoning": {}}]
            cached = self._schema_s
        order = ([cached] + [i for i in range(len(cands)) if i != cached]) \
            if cached is not None else list(range(len(cands)))
        for i in order:
            try:
                action.set_data(cands[i])
                if pend: self._schema_c = i
                else:    self._schema_s = i
                return "d%d:%s" % (i, ",".join(sorted(cands[i])))
            except Exception:
                continue
        return "FAILED"

    def do_action_request(self, action):
        wide = bool(int(self.hp.get("wide_lock", 0)))
        _ACT_LOCK.acquire()
        try:
            self.click_api = self._set_action_data(action)
            ad = getattr(action, "action_data", None)
            if hasattr(ad, "model_dump"):
                data = ad.model_dump()
            elif isinstance(ad, dict):
                data = dict(ad)
            else:
                data = {"game_id": str(getattr(self, "game_id", ""))}
                if self._pending_data: data.update(self._pending_data)
            if wide:
                raw = self.arc_env.step(action, data=data,
                                        reasoning=data.get("reasoning") or {})
                return self._convert_raw_frame_data(raw)
        finally:
            if not wide:
                _ACT_LOCK.release()
            else:
                _ACT_LOCK.release()
        raw = self.arc_env.step(action, data=data,
                                reasoning=data.get("reasoning") or {})
        # race detector: did another thread overwrite our coordinates?
        if self._pending_data:
            ad2 = getattr(action, "action_data", None)
            try:
                if int(getattr(ad2, "x", self._pending_data["x"])) != self._pending_data["x"] or \
                   int(getattr(ad2, "y", self._pending_data["y"])) != self._pending_data["y"]:
                    self.click_race += 1
            except Exception:
                pass
        return self._convert_raw_frame_data(raw)

    def take_action(self, action):                      # F6: never kill a thread
        try:
            out = super().take_action(action)
            self._errors = 0
            return out
        except Exception as e:
            self._errors += 1
            self._last_err = ("%s: %s" % (type(e).__name__, e))[:220]
            time.sleep(min(2.0, 0.05 * self._errors))
            return None

    # =================================================== episode life
    def _begin_episode(self) -> None:
        self.traj: List[tuple] = []; self.traj_states: List[bytes] = []
        self.ep_seen: Set[bytes] = set()
        self.ep_edge: Dict[Tuple[bytes, tuple], int] = defaultdict(int)
        self.visited_coords: Set[Tuple[int, int]] = set()
        self.steps_since_new = 0
        self.last_h = None; self.last_key = None
        self.last_grid = None; self.last_score = 0.0
        self.episodes += 1; self.gv += 1
        allow = (self.reset_preserves is not True)
        if allow and 0 < len(self.best_traj) <= int(self.hp["max_replay"]):
            self.replay = list(self.best_traj)
            self.replay_states = list(self.best_states)
        else:
            self.replay, self.replay_states = [], []
        self.replay_i = 0

    def is_done(self, frames, latest_frame) -> bool:               # F5
        try:
            if time.time() >= DEADLINE:
                return True
            if self._errors >= int(self.hp.get("max_consec_errors", 25)):
                return True
            if latest_frame is None:
                return False
            return _sname(getattr(latest_frame, "state", None)) == "WIN"
        except Exception:
            return False

    # =================================================== perception
    def _extract_grid(self, frame) -> Optional[np.ndarray]:
        raw = getattr(frame, "frame", getattr(frame, "grid", None)) if frame else None
        if raw is None or (hasattr(raw, "__len__") and len(raw) == 0):
            return None
        try:
            arr = np.array(raw, dtype=np.int16)
        except Exception:
            try: arr = np.array(raw[-1], dtype=np.int16)
            except Exception: return None
        while arr.ndim > 2:
            arr = arr[-1]
        return arr if (arr.ndim == 2 and arr.size > 0) else None

    @staticmethod
    def _get_score(f) -> float:
        for k in ("levels_completed", "score"):
            v = getattr(f, k, None)
            if isinstance(v, (int, float)): return float(v)
        return 0.0

    @staticmethod
    def _bg(grid) -> int:
        c, n = np.unique(grid, return_counts=True)
        return int(c[int(np.argmax(n))])

    def _block_size(self, grid) -> int:                            # F9
        if self._blk_shape == grid.shape and self.t % 97 != 0:
            return self._blk
        runs = []
        for g in (grid, grid.T):
            step = max(1, g.shape[0] // 8)
            for i in range(0, g.shape[0], step):
                row = g[i]
                idx = np.flatnonzero(np.diff(row)) + 1
                lens = np.diff(np.concatenate(([0], idx, [len(row)])))
                runs.extend(int(v) for v in lens if v > 0)
        b = 0
        for v in runs[:400]:
            b = gcd(b, v)
            if b == 1: break
        self._blk = max(1, min(16, b or 1)); self._blk_shape = grid.shape
        return self._blk

    def _update_volatility(self, grid) -> None:                    # F7
        v = self._vol
        if v is None or v["shape"] != grid.shape:
            self._vol = {"shape": grid.shape, "chg": np.zeros(grid.shape, np.int32),
                         "n": 0, "prev": grid.copy()}
            self._mask, self._mask_frozen = None, False
            return
        v["chg"] += (v["prev"] != grid); v["n"] += 1; v["prev"] = grid.copy()
        if not self._mask_frozen and v["n"] >= int(self.hp["vol_window"]):
            m = (v["chg"] / float(v["n"])) >= float(self.hp["vol_thresh"])
            self._mask = m if 0 < int(m.sum()) <= float(self.hp["vol_max_frac"]) * grid.size else None
            self._mask_frozen = True

    def _state_key(self, grid) -> bytes:
        g = grid
        if self._mask is not None and self._mask.shape == grid.shape:
            g = np.where(self._mask, np.int16(-1), grid)
        return hashlib.blake2b(g.astype(np.int16).tobytes() +
                               b"|%d,%d" % grid.shape, digest_size=16).digest()

    # =================================================== kinematics
    def _learn_motion(self, prev, curr, act_id) -> None:
        diff = prev != curr
        if not diff.any(): return
        moved = {}
        for c in set(np.unique(prev[diff]).tolist()) | set(np.unique(curr[diff]).tolist()):
            pp, pc = np.argwhere(prev == c), np.argwhere(curr == c)
            if len(pp) == 0 or len(pp) != len(pc) or len(pp) > prev.size // 4: continue
            sh = np.round(pc.mean(0) - pp.mean(0)).astype(int)
            if (sh != 0).any() and np.array_equal(pp + sh, pc):
                moved[int(c)] = (int(sh[0]), int(sh[1]))
        if not moved: return
        groups = defaultdict(list)
        for c, sh in moved.items(): groups[sh].append(c)
        sh, members = max(groups.items(),
                          key=lambda kv: len(kv[1]) + (5 if self.avatar_color in kv[1] else 0))
        d = np.array(sh, dtype=float)
        av = self.avatar_color if self.avatar_color in members else \
            min(members, key=lambda c: float(np.argwhere(prev == c).mean(0) @ d))
        self.avatar_votes[av] += 1
        if self.avatar_color is None or \
           self.avatar_votes[av] > self.avatar_votes.get(self.avatar_color, 0):
            self.avatar_color = av
        self.action_deltas[act_id] = (float(sh[0]), float(sh[1]))
        for c in members:
            if c != av:
                self.pushable_colors.add(c); self.wall_colors.discard(c)

    @property
    def avatar_ok(self) -> bool:
        return (self.avatar_color is not None
                and self.avatar_votes.get(self.avatar_color, 0) >= 2
                and len(self.action_deltas) >= 2)

    def _learn_wall(self, grid, act_id) -> None:
        if not self.avatar_ok or act_id not in self.action_deltas: return
        dy, dx = self.action_deltas[act_id]; H, W = grid.shape
        pts = np.argwhere(grid == self.avatar_color)
        if len(pts) == 0: return
        q = pts + np.array([int(round(dy)), int(round(dx))])
        q = q[(q[:, 0] >= 0) & (q[:, 0] < H) & (q[:, 1] >= 0) & (q[:, 1] < W)]
        if len(q) == 0: return
        bg = self._bg(grid)
        for c in np.unique(grid[q[:, 0], q[:, 1]]):
            c = int(c)
            if c in (bg, self.avatar_color) or c in self.pushable_colors: continue
            self.wall_votes[c] += 1
            if self.wall_votes[c] >= 2: self.wall_colors.add(c)

    def _collides(self, grid, pts, dy, dx) -> bool:
        if pts is None or len(pts) == 0: return False
        H, W = grid.shape
        q = pts + np.array([int(round(dy)), int(round(dx))])
        if (q < 0).any() or (q[:, 0] >= H).any() or (q[:, 1] >= W).any(): return True
        if not self.wall_colors: return False
        return bool(np.isin(grid[q[:, 0], q[:, 1]], list(self.wall_colors)).any())

    def _locate_avatar(self, grid):
        if not self.avatar_ok: return None, None, None
        pts = np.argwhere(grid == self.avatar_color)
        if len(pts) == 0: return None, None, None
        return (float(pts[:, 0].mean()), float(pts[:, 1].mean())), pts, self.avatar_color

    def _landmarks(self, grid, av_col):
        bg = self._bg(grid); out = []
        for c, cnt in zip(*np.unique(grid, return_counts=True)):
            c = int(c)
            if c in (bg, av_col) or c in self.wall_colors: continue
            if c in self.pushable_colors:
                out.append(tuple(np.argwhere(grid == c).mean(0)))
            elif cnt <= 6 * self._blk * self._blk:
                for y, x in np.argwhere(grid == c)[:12]:
                    if (int(y), int(x)) not in self.visited_coords:
                        out.append((float(y), float(x)))
        return out[:40]

    # =================================================== click priors
    def _prior(self, sig) -> float:
        if sig is None: return 0.5
        h, n = self.click_stats[sig]; return (h + 1.0) / (n + 2.0)

    def _strong(self, sig) -> bool:
        if sig is None: return False
        h, n = self.click_stats[sig]; return n >= 4 and (h / float(n)) >= 0.5

    def _eff(self, aid) -> float:
        h, n = self.aid_stats[aid]; return (h + 1.0) / (n + 2.0)

    def _click_candidates(self, grid, limit):
        H, W = grid.shape; bg = self._bg(grid); blk = self._block_size(grid)
        seen, out = set(), []

        def add(prio, y, x, sig):
            y, x = int(y), int(x)
            if 0 <= y < H and 0 <= x < W and (y, x) not in seen:
                seen.add((y, x)); out.append((prio, y, x, sig))

        # (a) symmetry completion
        tfs = [np.fliplr(grid), np.flipud(grid), np.rot90(grid, 2)]
        if H == W: tfs.append(grid.T)
        for t in tfs:
            if float(np.mean(t == grid)) < 0.85: continue
            m = (grid == bg) & (t != bg)
            lab, n = label_components(m)
            if 1 <= n <= 8:
                for i in range(1, int(n) + 1):
                    pts = np.argwhere(lab == i)
                    j = int(np.argmin(((pts - pts.mean(0)) ** 2).sum(1)))
                    add(0, pts[j, 0], pts[j, 1], ("sym", int(t[pts[j, 0], pts[j, 1]])))

        # (b) 3x3 anomalies (scaled by block size)
        if blk == 1:
            pad = np.pad(grid, 1, mode="edge"); same = np.zeros((H, W), np.int32)
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy or dx:
                        same += (pad[1+dy:1+dy+H, 1+dx:1+dx+W] == grid)
            odd = np.argwhere(same == 0)
            if len(odd) <= 16:
                for y, x in odd: add(1, y, x, ("odd", int(grid[y, x])))

        # (c) connected components ranked by learned signature prior
        comps = []
        for c in np.unique(grid):
            c = int(c)
            if c == bg: continue
            lab, n = label_components(grid == c)
            if n == 0 or n > 48: continue
            for i in range(1, int(n) + 1):
                pts = np.argwhere(lab == i)
                if len(pts) == 0: continue
                mn, mx = pts.min(0), pts.max(0)
                sig = ("obj", c, int(len(pts) // max(1, blk * blk)),
                       int((mx[0]-mn[0]+1) // blk), int((mx[1]-mn[1]+1) // blk))
                j = int(np.argmin(((pts - pts.mean(0)) ** 2).sum(1)))
                comps.append((sig, int(pts[j, 0]), int(pts[j, 1]), int(len(pts))))
        comps.sort(key=lambda t: (-self._prior(t[0]), t[3]))
        for sig, y, x, _ in comps[:limit]: add(2, y, x, sig)

        # (d) block-aligned lattice sweep
        for y in range(blk // 2, H, blk):
            for x in range(blk // 2, W, blk):
                add(3, y, x, ("lat", int(grid[y, x])))

        out.sort(key=lambda t: (0 if self._strong(t[3]) else 1, t[0], -self._prior(t[3])))
        return out[:limit]

    # =================================================== menus
    def _build_menu(self, h, grid, simple_ids, has_click):
        keys = [(a, None, None) for a in sorted(simple_ids)]
        if has_click:
            for _p, y, x, sig in self._click_candidates(
                    grid, int(self.hp["max_clicks_per_state"])):
                k = (6, y, x); keys.append(k); self.key_sig[(h, k)] = sig
        if len(self.menu) < int(self.hp["menu_cache_cap"]):
            self.menu[h] = keys; self.menu_ext[h] = 0
        return keys

    def _extend_menu(self, h, grid) -> bool:
        if 6 not in self.avail_ids or self.menu_ext.get(h, 9) >= 2: return False
        cur = self.menu.get(h)
        if cur is None or len(cur) >= int(self.hp["menu_hard_cap"]): return False
        self.menu_ext[h] = self.menu_ext.get(h, 0) + 1
        H, W = grid.shape; blk = max(1, self._blk)
        have = {(k[1], k[2]) for k in cur if k[1] is not None}
        step = max(1, blk // 2) if self.menu_ext[h] == 1 else 1
        extra = [(y, x) for y in range(0, H, step) for x in range(0, W, step)
                 if (y, x) not in have]
        self.rng.shuffle(extra)
        extra = extra[:int(self.hp["menu_hard_cap"]) - len(cur)]
        for y, x in extra:
            k = (6, int(y), int(x)); cur.append(k)
            self.key_sig[(h, k)] = ("lat", int(grid[y, x]))
        return bool(extra)

    # =================================================== graph search
    def _edges(self, node):
        for k, nxt in self.adj.get(node, {}).items():
            if nxt is node or nxt in self.dead: continue
            if (node, k) in self.trap_edges: continue
            yield k, nxt

    def _want_reward(self, node):
        cap = int(self.hp["edge_repeat_cap"])
        for k, r in sorted(self.reward_at.get(node, {}).items(), key=lambda kv: -kv[1]):
            if (node, k) in self.trap_edges or self.ep_edge[(node, k)] >= cap: continue
            return k
        return None

    def _want_untried(self, node):
        m = self.menu.get(node)
        if not m: return None
        tr = self.tried.get(node, ())
        for k in m:
            if k not in tr and (node, k) not in self.trap_edges: return k
        return None

    def _bfs(self, start, want):
        budget = int(self.hp["bfs_max_nodes"]); seen = {start}; q = deque(); n = 0
        for k, nxt in self._edges(start):
            if nxt in seen: continue
            seen.add(nxt); q.append((nxt, k))
        while q:
            node, first = q.popleft(); n += 1
            if n > budget: return None
            if want(node) is not None: return first
            for k, nxt in self._edges(node):
                if nxt in seen: continue
                seen.add(nxt); q.append((nxt, first))
        return None

    def _bfs_cached(self, h, kind):
        e = self._memo.get((h, kind))
        if e is not None and e[0] == self.gv: return e[1]
        k = self._bfs(h, self._want_reward if kind == "r" else self._want_untried)
        if len(self._memo) > 20000: self._memo.clear()
        self._memo[(h, kind)] = (self.gv, k)
        return k

    def _shortest_path(self, src, dst, cap=4000):
        if src == dst: return [], []
        prev = {src: None}; q = deque([src]); n = 0
        while q:
            node = q.popleft(); n += 1
            if n > cap: return None
            for k, nxt in self._edges(node):
                if nxt in prev: continue
                prev[nxt] = (node, k)
                if nxt == dst:
                    keys, states, cur = [], [], nxt
                    while prev[cur] is not None:
                        pnode, kk = prev[cur]
                        keys.append(kk); states.append(pnode); cur = pnode
                    return keys[::-1], states[::-1]
                q.append(nxt)
        return None

    def _mark_dead(self, h) -> None:
        if h in self.dead: return
        self.dead.add(h); self.gv += 1
        q = deque([h]); n = 0
        while q and n < 3000:
            cur = q.popleft(); n += 1
            for ph, _pk in list(self.rev.get(cur, ())):
                if ph in self.dead or self.reward_at.get(ph): continue
                m = self.menu.get(ph)
                if not m: continue
                tr = self.tried.get(ph, set()); ok = True
                for k in m:
                    if k not in tr: ok = False; break
                    nxt = self.T.get((ph, k))
                    if (ph, k) in self.trap_edges or nxt == ph: continue
                    if nxt is None or nxt not in self.dead: ok = False; break
                if ok:
                    self.dead.add(ph); q.append(ph)

    # =================================================== observation
    def _observe(self, h, grid, score, frame) -> None:
        self.visits[h] += 1
        if h in self.ep_seen: self.steps_since_new += 1
        else: self.ep_seen.add(h); self.steps_since_new = 0

        # F8: learn whether RESET wipes progress or only restarts the level
        if self._await_reset:
            self._await_reset = False
            if self.reset_preserves is None and self._pre_reset_score > 0:
                self.reset_preserves = bool(score >= self._pre_reset_score)
                if self.reset_preserves:
                    self.replay, self.replay_states, self.replay_i = [], [], 0
            self.last_score = score

        lh, lk = self.last_h, self.last_key
        if lh is not None and lk is not None:
            changed = (h != lh)
            if (lh, lk) not in self.T: self.gv += 1
            self.T[(lh, lk)] = h
            if changed:
                if lk not in self.adj[lh]: self.gv += 1
                self.adj[lh][lk] = h; self.rev[h].add((lh, lk))

            st = self.aid_stats[lk[0]]; st[1] += 1
            if changed: st[0] += 1
            if lk[1] is not None:
                sig = self.key_sig.get((lh, lk))
                if sig is not None:
                    cs = self.click_stats[sig]; cs[1] += 1
                    if changed: cs[0] += 1

            d = score - self.last_score
            if d > 0:
                self.reward_at[lh][lk] = max(self.reward_at[lh].get(lk, 0.0), d)
                self.gv += 1
                if lk[1] is not None:
                    sig = self.key_sig.get((lh, lk))
                    if sig is not None: self.click_stats[sig][0] += 3

            if lk[1] is None and self.last_grid is not None \
                    and self.last_grid.shape == grid.shape:
                if changed: self._learn_motion(self.last_grid, grid, lk[0])
                else: self._learn_wall(grid, lk[0])

        if score > self.best_score:
            self.best_score = score
            traj, states = list(self.traj), list(self.traj_states)
            if states:
                sp = self._shortest_path(states[0], h)
                if sp is not None and len(sp[0]) < len(traj): traj, states = sp
            self.best_traj, self.best_states = traj, states

        self.last_score = score

    def _on_death(self) -> None:
        self.deaths += 1; self.gv += 1
        if self.last_h is not None and self.last_key is not None:
            self.trap_edges.add((self.last_h, self.last_key))
            self.tried[self.last_h].add(self.last_key)
            if 0 < self.replay_i <= len(self.replay) and \
               self.replay[self.replay_i - 1] == self.last_key:
                self.best_traj, self.best_states, self.best_score = [], [], 0.0

    # =================================================== local choice
    def _simple_pref(self, h, grid, k) -> float:
        aid = k[0]; pref = 2.0 * self._eff(aid) + 0.01 * self.rng.random()
        if self.av_pos is not None and aid in self.action_deltas:
            dy, dx = self.action_deltas[aid]
            if self._collides(grid, self.av_pts, dy, dx):
                pref -= float(self.hp["wall_penalty"])
            else:
                ny, nx = self.av_pos[0] + dy, self.av_pos[1] + dx
                if (int(round(ny)), int(round(nx))) not in self.visited_coords:
                    pref += float(self.hp["unvisited_bonus"])
                if self.landmarks:
                    t = min(self.landmarks, key=lambda p: abs(self.av_pos[0]-p[0]) +
                                                          abs(self.av_pos[1]-p[1]))
                    pref += float(self.hp["landmark_weight"]) * (
                        (abs(self.av_pos[0]-t[0]) + abs(self.av_pos[1]-t[1]))
                        - (abs(ny-t[0]) + abs(nx-t[1])))
        return pref

    def _pick_local(self, h, grid, menu):
        tr = self.tried.get(h, set())
        untried = [k for k in menu if k not in tr and (h, k) not in self.trap_edges
                   and k[0] in self.avail_ids]
        if not untried: return None
        simple = [k for k in untried if k[1] is None and self._eff(k[0]) >= 0.15]
        weak   = [k for k in untried if k[1] is None and self._eff(k[0]) < 0.15]
        clicks = [k for k in untried if k[1] is not None]
        if simple: return max(simple, key=lambda k: self._simple_pref(h, grid, k))
        if clicks:
            clicks.sort(key=lambda k: (-int(self._strong(self.key_sig.get((h, k)))),
                                       -self._prior(self.key_sig.get((h, k)))))
            return clicks[0]
        if weak: return max(weak, key=lambda k: self._simple_pref(h, grid, k))
        return None

    # =================================================== main policy
    def choose_action(self, frames, latest_frame):
        try:
            return self._choose(frames, latest_frame)
        except Exception as e:                                   # F6
            self._last_err = ("choose:%s:%s" % (type(e).__name__, e))[:220]
            self.mode_counts["exception"] += 1
            self._pending_data = None
            try:
                pool = [a for a in (self.act_by_id or {}).values()]
                return self.rng.choice(pool) if pool else self._reset_action()
            except Exception:
                return self._reset_action()

    def _reset_action(self):
        self._pending_data = None
        self._pre_reset_score = self.last_score
        self._await_reset = True
        return GameAction.RESET

    def _choose(self, frames, latest_frame):
        self.t += 1
        st = _sname(getattr(latest_frame, "state", None))

        if latest_frame is None or st == "NOT_PLAYED":
            self._begin_episode(); return self._reset_action()

        if st == "GAME_OVER":
            self._on_death(); self.resets += 1
            self._begin_episode(); self._dump_stats()
            return self._reset_action()

        grid = self._extract_grid(latest_frame)
        if grid is None:
            self._begin_episode(); return self._reset_action()

        score = self._get_score(latest_frame)
        self._update_volatility(grid)
        self._block_size(grid)
        h = self._state_key(grid)
        self._observe(h, grid, score, latest_frame)

        raw = getattr(latest_frame, "available_actions", None) or [1, 2, 3, 4, 5]
        acts = []
        for a in raw:
            ca = a if hasattr(a, "value") else GameAction(int(a))
            if _aid(ca) > 0: acts.append(ca)
        if not acts:
            acts = [GameAction.ACTION1]
        self.act_by_id = {_aid(a): a for a in acts}
        self.avail_ids = set(self.act_by_id.keys())
        simple_ids = sorted(i for i in self.avail_ids if 1 <= i <= 5)
        has_click = 6 in self.avail_ids

        self.av_pos, self.av_pts, av_col = self._locate_avatar(grid)
        if self.av_pos is not None:
            self.visited_coords.add((int(round(self.av_pos[0])), int(round(self.av_pos[1]))))
            self.landmarks = self._landmarks(grid, av_col)
        else:
            self.landmarks = []

        menu = self.menu.get(h)
        if menu is None:
            menu = self._build_menu(h, grid, simple_ids, has_click)

        # TIER 0 — Go-Explore replay
        if self.replay_i < len(self.replay):
            k = self.replay[self.replay_i]
            exp = self.replay_states[self.replay_i] \
                if self.replay_i < len(self.replay_states) else None
            if exp == h and (h, k) not in self.trap_edges and k[0] in self.avail_ids:
                self.replay_i += 1; self.replay_steps += 1
                self.mode_counts["replay"] += 1
                return self._finish(k, h, grid)
            self.replay, self.replay_states, self.replay_i = [], [], 0
            self.mode_counts["replay_abort"] += 1

        if self.steps_since_new >= int(self.hp["stagnation_limit"]):
            self.resets += 1; self._begin_episode(); self._dump_stats()
            return self._reset_action()

        k, mode = self._policy(h, grid, menu)
        if k is None:
            self._mark_dead(h); self.resets += 1
            self._begin_episode(); self._dump_stats()
            return self._reset_action()

        self.mode_counts[mode] += 1
        if self.t % int(self.hp["stats_every"]) == 0: self._dump_stats()
        return self._finish(k, h, grid)

    def _policy(self, h, grid, menu):
        cap = int(self.hp["edge_repeat_cap"])
        for k, r in sorted(self.reward_at.get(h, {}).items(), key=lambda kv: -kv[1]):
            if (h, k) in self.trap_edges or self.ep_edge[(h, k)] >= cap: continue
            if k[0] in self.avail_ids: return k, "exploit"
        k = self._bfs_cached(h, "r")
        if k is not None and k[0] in self.avail_ids: return k, "nav_reward"
        k = self._pick_local(h, grid, menu)
        if k is not None: return k, "explore"
        k = self._bfs_cached(h, "u")
        if k is not None and k[0] in self.avail_ids: return k, "nav_frontier"
        if self._extend_menu(h, grid):
            self.gv += 1
            k = self._pick_local(h, grid, self.menu[h])
            if k is not None: return k, "explore_ext"
        return None, "dead"

    def _finish(self, key, h, grid):
        self.tried[h].add(key)
        self.ep_edge[(h, key)] += 1
        if self.ep_edge[(h, key)] >= int(self.hp["edge_repeat_cap"]): self.gv += 1
        self.traj.append(key); self.traj_states.append(h)
        self.last_h, self.last_key, self.last_grid = h, key, grid.copy()
        act = self.act_by_id.get(key[0]) or GameAction.ACTION1
        if key[1] is not None:
            H, W = grid.shape
            self._pending_data = {"x": int(np.clip(key[2], 0, max(0, W - 1))),
                                  "y": int(np.clip(key[1], 0, max(0, H - 1)))}
        else:
            self._pending_data = None
        return act

    # =================================================== telemetry
    def _dump_stats(self) -> None:
        try:
            el = max(0.1, time.time() - self._t0)
            payload = {
                "game_id": str(getattr(self, "game_id", "?")),
                "engine": ENGINE_SRC, "engine_ok": ENGINE_OK, "base_real": BASE_REAL,
                "steps": self.t, "actions": int(getattr(self, "action_counter", 0)),
                "fps": round(self.t / el, 2),
                "episodes": self.episodes, "deaths": self.deaths, "resets": self.resets,
                "best_score": self.best_score, "last_score": self.last_score,
                "best_traj_len": len(self.best_traj), "replay_steps": self.replay_steps,
                "reset_preserves": self.reset_preserves,
                "states_known": len(self.visits), "edges_known": len(self.T),
                "traps": len(self.trap_edges), "dead_states": len(self.dead),
                "block_size": self._blk,
                "masked_cells": int(self._mask.sum()) if self._mask is not None else 0,
                "avatar_color": self.avatar_color, "avatar_ok": bool(self.avatar_ok),
                "action_deltas": {str(k): v for k, v in self.action_deltas.items()},
                "wall_colors": sorted(self.wall_colors),
                "click_api": self.click_api, "click_race": self.click_race,
                "errors": self._errors, "last_err": self._last_err,
                "modes": dict(self.mode_counts), "wall_time_s": round(el, 1),
            }
            os.makedirs(os.path.dirname(self._stats_path), exist_ok=True)
            with open(self._stats_path, "w") as f:
                json.dump(payload, f, indent=1)
        except Exception:
            pass
'''

