        ag._update_volatility(g); ag._state_key(g)
    assert ag._mask is not None and ag._mask[0, 0], "HUD not detected as volatile"
    tail = set()
    for i in range(130, 170):
        g = base.copy(); g[0, 0:3] = (i % 7) + 1
        ag._update_volatility(g); tail.add(ag._state_key(g))
    assert len(tail) == 1, f"masked key unstable: {len(tail)} keys"


def test_trap_is_never_repeated():
    ag = MyAgent(game_id="t_trap")
    g = np.zeros((8, 8), np.int16); g[4, 4] = 2
    f = _frame(g, acts=(1, 2))
    ag.choose_action([f], f)
    tk, th = ag.last_key, ag.last_h
    r = ag.choose_action([f], _frame(g, GameState.GAME_OVER, acts=(1, 2)))
    assert _aid(r) == 0, f"expected RESET, got {r}"
    assert (th, tk) in ag.trap_edges
    ag.choose_action([f], f)
    assert ag.last_key != tk, "agent repeated a fatal transition"


