def test_graph_navigation():
    from collections import defaultdict as dd
    ag = MyAgent(game_id="t_nav")
    k1, k2 = (1, None, None), (2, None, None)
    S = [b"S%d" % i for i in range(4)]
    for i in range(3):
        ag.adj[S[i]][k1] = S[i+1]; ag.T[(S[i], k1)] = S[i+1]
        ag.rev[S[i+1]].add((S[i], k1))
        ag.menu[S[i]] = [k1, k2]; ag.tried[S[i]] = {k1, k2}
    ag.menu[S[3]] = [k1, k2]; ag.tried[S[3]] = {k1}
    ag.ep_edge = dd(int)
    assert ag._bfs(S[0], ag._want_untried) == k1
    ag.reward_at[S[2]][k2] = 1.0
    assert ag._bfs(S[0], ag._want_reward) == k1


