class GridWorld:
    ACTS = (1, 2, 3, 4, 5)
    MOVES = {1: (-1, 0), 2: (1, 0), 3: (0, -1), 4: (0, 1)}
    LEVELS = 3
    SPOTS = [(1, 1), (1, 11), (11, 1), (11, 11), (1, 5),
             (5, 1), (7, 9), (9, 7), (3, 7), (7, 3)]

    def __init__(self, lava=False, name="mock_grid"):
        self.lava_on = lava; self.name = name; self.reset_all()

    def reset_all(self):
        self.level = 0; self.deaths = 0
        self.state = GameState.NOT_PLAYED; self._build()

    def _build(self):
        H = W = 13
        g = np.zeros((H, W), np.int16)
        g[0, :] = g[-1, :] = g[:, 0] = g[:, -1] = 8
        for y in range(2, H - 1, 2):
            for x in range(2, W - 1, 2): g[y, x] = 8
        self.base = g; i = self.level
        self.pos = list(self.SPOTS[i % len(self.SPOTS)])
        self.goal = self.SPOTS[(i + 3) % len(self.SPOTS)]
        self.lava = {self.SPOTS[(i + 5) % len(self.SPOTS)]} if self.lava_on else set()

    def grid(self):
        g = self.base.copy()
        for (y, x) in self.lava: g[y, x] = 9
        g[self.goal] = 5; g[self.pos[0], self.pos[1]] = 2
        return g

    def frame(self): return _frame(self.grid(), self.state, self.level, self.ACTS)

    def step(self, aid, y=None, x=None):
        if aid == 0:
            self.level = 0; self._build(); self.state = GameState.NOT_FINISHED; return
        if self.state in (GameState.NOT_PLAYED, GameState.GAME_OVER):
            self.state = GameState.NOT_FINISHED; return
        if aid in self.MOVES:
            dy, dx = self.MOVES[aid]
            ny, nx = self.pos[0] + dy, self.pos[1] + dx
            if self.base[ny, nx] != 8: self.pos = [ny, nx]
            if tuple(self.pos) in self.lava:
                self.state = GameState.GAME_OVER; self.deaths += 1; return
            if tuple(self.pos) == self.goal:
                self.level += 1
                if self.level >= self.LEVELS: self.state = GameState.WIN
                else: self._build()


class ClickWorld:
    """64x64 frame, 8x8 logical blocks — matches real ARC-AGI-3 rendering."""
    ACTS = (1, 2, 3, 4, 5, 6); LEVELS = 5; name = "mock_click"; BLK = 8

    def __init__(self): self.reset_all()

    def reset_all(self):
        self.level = 0; self.deaths = 0
        self.state = GameState.NOT_PLAYED; self._build()

    def _build(self):
        rng = np.random.RandomState(11 + self.level)
        small = np.zeros((8, 8), np.int16)
        for c, n in ((3, 6), (4, 4), (5, 3)):
            for _ in range(n):
                small[rng.randint(0, 8), rng.randint(0, 8)] = c
        ty, tx = int(rng.randint(0, 8)), int(rng.randint(0, 8))
        small[ty, tx] = 7
        self.small = small; self.target = (ty, tx)
        self.g = np.kron(small, np.ones((self.BLK, self.BLK), np.int16))

    def frame(self): return _frame(self.g, self.state, self.level, self.ACTS)

    def step(self, aid, y=None, x=None):
        if aid == 0:
            self.level = 0; self._build(); self.state = GameState.NOT_FINISHED; return
        if self.state is GameState.NOT_PLAYED:
            self.state = GameState.NOT_FINISHED; return
        if aid == 6 and y is not None:
            if (int(y) // self.BLK, int(x) // self.BLK) == self.target:
                self.level += 1
                if self.level >= self.LEVELS: self.state = GameState.WIN
                else: self._build()


def run_bench(env, budget):
    ag = MyAgent(game_id=env.name); used = budget
    for i in range(budget):
        f = env.frame()
        if f.state is GameState.WIN: used = i; break
        a = ag.choose_action([f], f); aid = _aid(a)
        d = ag._pending_data or {}
        env.step(aid, d.get("y"), d.get("x"))
    return env.level, used, env.deaths, ag


